### JavaScript
```javascript
class RadialSlider {
  constructor(container) {
    this.container = container;
    this.svg = container.querySelector('.radial-slider-svg');
    this.circle = container.querySelector('.radial-slider-circle');
    this.markers = container.querySelector('.radial-slider-markers');
    this.handle = container.querySelector('.radial-slider-handle');
    this.valueDisplay = container.querySelector('.radial-slider-value');

    this.minRadius = 50;
    this.maxRadius = 150;
    this.numMarkers = 5;

    this.initMarkers();
    this.initHandle();

    this.updateValueDisplay();
  }

  initMarkers() {
    for (let i = 0; i < this.numMarkers; i++) {
      const radius = this.minRadius + (i / (this.numMarkers - 1)) * (this.maxRadius - this.minRadius);
      const circle = document.createElementNS('http://www.w3.org/2000/svg', 'circle');
      circle.setAttribute('cx', 150);
      circle.setAttribute('cy', 150);
      circle.setAttribute('r', radius);
      circle.setAttribute('fill', 'none');
      circle.setAttribute('stroke', '#ccc');
      circle.setAttribute('stroke-width', 1);
      this.markers.appendChild(circle);
    }
  }

  initHandle() {
    let isDragging = false;
    let initialAngle = 0;
    let initialRadius = this.minRadius;

    this.handle.addEventListener('mousedown', (e) => {
      isDragging = true;
      initialAngle = Math.atan2(e.clientY - 150, e.clientX - 150);
      initialRadius = this.getRadiusFromEvent(e);
    });

    document.addEventListener('mousemove', (e) => {
      if (isDragging) {
        const newRadius = this.getRadiusFromEvent(e);
        this.circle.setAttribute('r', newRadius);
        this.handle.setAttribute('cy', 150 + newRadius * Math.sin(Math.atan2(e.clientY - 150, e.clientX - 150)));
        this.handle.setAttribute('cx', 150 + newRadius * Math.cos(Math.atan2(e.clientY - 150, e.clientX - 150)));
        this.updateValueDisplay(newRadius);
      }
    });

    document.addEventListener('mouseup', () => {
      isDragging = false;
    });
  }

  getRadiusFromEvent(e) {
    const dx = e.clientX - 150;
    const dy = e.clientY - 150;
    const radius = Math.sqrt(dx * dx + dy * dy);
    return Math.min(Math.max(radius, this.minRadius), this.maxRadius);
  }

  updateValueDisplay(radius = this.minRadius) {
    this.valueDisplay.textContent = Math.round(radius);
  }
}

