To illustrate a blocking read operation that is interrupted by a signal and how to handle the `EINTR` error that results from it, we'll use a simple example in C. This program will set up a signal handler, then perform a blocking read operation on the standard input (usually the keyboard). While waiting for input, we'll send a signal to the process to simulate the interruption.

Here's a step-by-step breakdown of what the example will do:

1. Set up a signal handler for `SIGUSR1`, a signal that we can send to the process using the `kill` command.
2. Perform a blocking read on `STDIN_FILENO`.

Let's dive into the code:

```c
#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

void sigusr1_handler(int signum) {
    if (signum == SIGUSR1) {
        printf("Received SIGUSR1\n");
    }
}

int main() {
    // Set up the signal handler for SIGUSR1
    struct sigaction sa;
    sa.sa_handler = &sigusr1_handler;
    sigemptyset(&sa.sa_mask);
    sa.sa_flags = 0;
    if (sigaction(SIGUSR1, &sa, NULL) == -1) {
        perror("sigaction");
        exit(EXIT_FAILURE);
    }

    printf("My PID is: %d\n", getpid());
    printf("You can send SIGUSR1 to me using: kill -SIGUSR1 %d\n", getpid());

    char buffer[256];
    ssize_t bytes_read;

    printf("Going into blocking read. Type something and press Enter.\n");
    printf("Or, send SIGUSR1 to interrupt the read.\n");

    while (1) {
        // Blocking read
        bytes_read = read(STDIN_FILENO, buffer, sizeof(buffer) - 1);
        if (bytes_read == -1) {
            if (errno == EINTR) {
                printf("Read was interrupted by a signal.\n");
                continue; // Try reading again
            } else {
                perror("read");
                exit(EXIT_FAILURE);
            }
        }

        // Null-terminate the buffer to treat it as a string
        buffer[bytes_read] = '\0';
        printf("Read: %s", buffer);

        // Exit after a successful read
        break;
    }

    return 0;
}
```

### How to use this example:

1. Compile the program: `gcc -o blocking_read_example blocking_read_example.c`
2. Run it: `./blocking_read_example`
3. The program will display its PID and instructions on how to send `SIGUSR1`.
4. You can either type something and press Enter to fulfill the read operation, or from another terminal, send `SIGUSR1` to the process using the `kill` command as instructed by the program's output.
5. If you send `SIGUSR1`, the `read` call will be interrupted, and the program will handle the `EINTR` error by retrying the read.

This example demonstrates how a blocking `read` operation can be interrupted by a signal and how to handle the resulting `EINTR` error by retrying the operation.

To read network packets from a socket on a specific port (in this case, port 888), you will first need to create a socket, bind it to the specified port, and then listen for incoming connections or directly receive data if you're working with a connectionless protocol like UDP. Below is a simple example using C++ for both TCP and UDP sockets.

### TCP Server Example

For a TCP server, you need to create a socket, bind it to a port, listen for incoming connections, accept a connection, and then receive data from the connected client.

```cpp
#include <iostream>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <string.h>

#define PORT 888
#define BUFFER_SIZE 1024

int main() {
    int server_fd, client_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd < 0) {
        std::cerr << "Error creating socket." << std::endl;
        return -1;
    }

    // Set address and port number for the server
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the port
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        std::cerr << "Error binding socket to port " << PORT << "." << std::endl;
        close(server_fd);
        return -1;
    }

    // Listen for incoming connections
    if (listen(server_fd, 3) < 0) { // Allow up to 3 queued connections
        std::cerr << "Error listening on socket." << std::endl;
        close(server_fd);
        return -1;
    }

    std::cout << "Server listening on port " << PORT << "..." << std::endl;

    while (true) {
        // Accept an incoming connection
        client_fd = accept(server_fd, (struct sockaddr *)&client_addr, &client_len);
        if (client_fd < 0) {
            std::cerr << "Error accepting client connection." << std::endl;
            continue;
        }

        std::cout << "Connection accepted from client IP address "
                  << ntohl(client_addr.sin_addr.s_addr) << " and port "
                  << ntohs(client_addr.sin_port) << "." << std::endl;

        // Receive data from the client
        memset(buffer, 0, BUFFER_SIZE);
        int bytes_received = recv(client_fd, buffer, BUFFER_SIZE, 0);
        if (bytes_received < 0) {
            std::cerr << "Error receiving data from client." << std::endl;
        } else {
            std::cout << "Received " << bytes_received << " bytes: " << buffer << std::endl;
        }

        // Close the client socket
        close(client_fd);
    }

    // Close the server socket
    close(server_fd);
    return 0;
}
```

### UDP Server Example

For a UDP server, you create a socket, bind it to a port, and then directly receive data from clients without establishing a connection.

```cpp
#include <iostream>
#include <sys/socket.h>
#include <netinet/in.h>
#include <unistd.h>
#include <string.h>

#define PORT 888
#define BUFFER_SIZE 1024

int main() {
    int server_fd;
    struct sockaddr_in server_addr, client_addr;
    socklen_t client_len = sizeof(client_addr);
    char buffer[BUFFER_SIZE];

    // Create socket
    server_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (server_fd < 0) {
        std::cerr << "Error creating socket." << std::endl;
        return -1;
    }

    // Set address and port number for the server
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(PORT);
    server_addr.sin_addr.s_addr = INADDR_ANY;

    // Bind the socket to the port
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        std::cerr << "Error binding socket to port " << PORT << "." << std::endl;
        close(server_fd);
        return -1;
    }

    std::cout << "UDP Server listening on port " << PORT << "..." << std::endl;

    while (true) {
        // Receive data from a client
        memset(buffer, 0, BUFFER_SIZE);
        int bytes_received = recvfrom(server_fd, buffer, BUFFER_SIZE, 0, (struct sockaddr *)&client_addr, &client_len);
        if (bytes_received < 0) {
            std::cerr << "Error receiving data." << std::endl;
            continue;
        }

        std::cout << "Received " << bytes_received << " bytes from client IP address "
                  << ntohl(client_addr.sin_addr.s_addr) << " and port "
                  << ntohs(client_addr.sin_port) << ": " << buffer << std::endl;
    }

    // Close the server socket
    close(server_fd);
    return 0;
}
```

These examples demonstrate the basic steps for creating a TCP or UDP server that listens on port 888 and reads incoming data. For a complete application, you should also consider handling disconnections, implementing protocol-specific logic, and potentially using more advanced networking APIs or libraries for better performance and scalability.

To achieve a 500x500 pixel square with the top right corner rounded in After Effects using an expression on the path property of a shape layer, you can use the following expression. This expression assumes you want to control the radius of the rounded corner.

First, create a new shape layer, then add a new shape to it (e.g., by clicking on "Add: Rectangle" in the layer's content settings). You can then right-click on the "Path" property under the shape's "Rectangle 1" settings and choose "Separate Dimensions" if it's not already separated, and then right-click again on "Path" to choose "Edit Expression".

Here's an expression that will create a 500x500 square with the top right corner rounded. The radius of the rounded corner can be controlled by adjusting the `cornerRadius` variable at the beginning of the expression.

```javascript
// Control the radius of the rounded corner
var cornerRadius = 100; // Adjust this value to change the corner radius

// Define the size of the square
var size = 500;

// Create an array to hold the path points
var path = createPath();

// Function to create the path
function createPath(){
  var shape = [];

  // Start at the bottom left
  shape[0] = [0, size];

  // Line to bottom right
  shape[1] = [size, size];

  // Line to top right, with a rounded corner
  var numPoints = 10; // More points = smoother curve
  for (var i = 0; i <= numPoints; i++) {
    var t = i / numPoints;
    var x = size;
    var y = 0 + cornerRadius * (1 - Math.cos(t * Math.PI / 2));
    var px = size - cornerRadius + cornerRadius * Math.sin(t * Math.PI / 2);
    shape.push([px, y]);
  }

  // Line to top left
  shape.push([0, 0]);

  // Close the path back to the start
  shape.push(shape[0]);

  return shape;
}

path;
```

This expression creates a square path where the top right corner is rounded. The `cornerRadius` variable controls how rounded the corner is. The path is defined in a clockwise direction starting from the bottom left corner.

To make the expression more flexible, you might want to link the `size` and `cornerRadius` variables to sliders or other properties so you can easily animate or adjust them.

To do this, you can create a Slider Control effect on your layer (Effect > Expression Controls > Slider Control), name it something like "Corner Radius", and then replace the `cornerRadius` variable with a reference to this slider. For example, if your Slider Control is named "Corner Radius", you would use:

```javascript
var cornerRadius = thisLayer.effect("Corner Radius")("Slider");
```

This allows you to dynamically adjust the corner radius using the slider.

To accomplish the task of merging two Word documents (.docx) into one using the OpenXML SDK in C#, while selectively taking elements from each document, we need to follow a detailed process. The OpenXML SDK allows us to manipulate Office documents by directly accessing their XML structure.

The task involves several steps:

1. **Open the source documents**: Open both .docx files using the OpenXML SDK.
2. **Extract required parts from the first document**: Take the first 2 pages, header, footer, and design elements (like fonts and styles) from the first document.
3. **Extract required parts from the second document**: Extract page contents and glossary from the second document.
4. **Create a new document**: Create a new .docx file and merge the extracted parts into it.

Below is a simplified example to guide you through this process. Note that directly manipulating OpenXML can be complex due to the intricacies of the Office Open XML format. This example provides a basic framework and may need adjustments based on the specifics of your documents and requirements.

### Step 1: Install OpenXML SDK

First, ensure you have the OpenXML SDK installed. You can do this via NuGet Package Manager in Visual Studio:

```powershell
Install-Package DocumentFormat.OpenXml
```

### Step 2: Implement the Merge Functionality

Here's a basic implementation in C#:

```csharp
using DocumentFormat.OpenXml;
using DocumentFormat.OpenXml.Packaging;
using DocumentFormat.OpenXml.Wordprocessing;
using System;
using System.IO;
using System.Linq;

public class WordDocumentMerger
{
    public void MergeDocuments(string filePath1, string filePath2, string outputFilePath)
    {
        using (WordprocessingDocument doc1 = WordprocessingDocument.Open(filePath1, true))
        using (WordprocessingDocument doc2 = WordprocessingDocument.Open(filePath2, true))
        using (WordprocessingDocument outputDoc = WordprocessingDocument.Create(outputFilePath, WordprocessingDocumentType.Document))
        {
            // Create the main document part
            MainDocumentPart mainPart = outputDoc.AddMainDocumentPart();
            mainPart.Document = new Document();

            // Copy styles, headers, footers, etc., from the first document
            CopyStyles(doc1.MainDocumentPart, mainPart);
            CopyHeaders(doc1.MainDocumentPart, mainPart);
            CopyFooters(doc1.MainDocumentPart, mainPart);

            // Copy the first 2 pages from the first document
            Body outputBody = mainPart.Document.Body ?? mainPart.Document.AppendChild(new Body());
            var body1 = doc1.MainDocumentPart.Document.Body;
            var paras = body1.Elements<Paragraph>().Take(20); // Simplified, assumes 10 paras per page
            foreach (var para in paras)
            {
                outputBody.AppendChild(para.CloneNode(true));
            }

            // Copy content from the second document
            var body2 = doc2.MainDocumentPart.Document.Body;
            foreach (var element in body2.Elements())
            {
                if (!(element is Paragraph || element is Table)) continue; // Simplify, consider other elements if needed
                outputBody.AppendChild(element.CloneNode(true));
            }

            // Handle glossary document part if present
            if (doc2.GlossaryDocumentPart != null)
            {
                var glossaryPart = outputDoc.AddGlossaryDocumentPart();
                glossaryPart.GlossaryDocument = (GlossaryDocument)doc2.GlossaryDocumentPart.GlossaryDocument.CloneNode(true);
            }

            // Save changes
            mainPart.Document.Save();
        }
    }

    private void CopyStyles(MainDocumentPart sourcePart, MainDocumentPart targetPart)
    {
        if (sourcePart.StyleDefinitionsPart != null)
        {
            var stylesPart = targetPart.AddNewPart<StyleDefinitionsPart>();
            stylesPart.Styles = (Styles)sourcePart.StyleDefinitionsPart.Styles.CloneNode(true);
        }
    }

    private void CopyHeaders(MainDocumentPart sourcePart, MainDocumentPart targetPart)
    {
        foreach (var headerPart in sourcePart.HeaderParts)
        {
            var newHeaderPart = targetPart.AddNewPart<HeaderPart>();
            newHeaderPart.Header = (Header)headerPart.Header.CloneNode(true);
            // Relationship Ids need to be correctly managed for images, etc.
        }
    }

    private void CopyFooters(MainDocumentPart sourcePart, MainDocumentPart targetPart)
    {
        foreach (var footerPart in sourcePart.FooterParts)
        {
            var newFooterPart = targetPart.AddNewPart<FooterPart>();
            newFooterPart.Footer = (Footer)footerPart.Footer.CloneNode(true);
            // Again, manage relationship Ids for any embedded content
        }
    }
}
```

### Step 3: Usage

To use this class, simply instantiate it and call `MergeDocuments`:

```csharp
class Program
{
    static void Main(string[] args)
    {
        WordDocumentMerger merger = new WordDocumentMerger();
        merger.MergeDocuments("document1.docx", "document2.docx", "output.docx");
    }
}
```

### Considerations

1. **Page Extraction**: The example simplifies page extraction by assuming a certain number of paragraphs per page. In reality, page breaks can be more complex (e.g., section breaks, different page sizes).
2. **Images and Other Media**: When copying elements, you must also manage the relationship IDs for any embedded media (images, etc.) to ensure they are correctly referenced in the new document.
3. **Glossary Document**: The example attempts to copy the glossary document part directly. Ensure this works with your specific use case.

This code provides a basic starting point. Real-world documents can have many complexities (e.g., different headers/footers for different sections, complex tables, tracked changes), so you may need to extend or modify this code to fit your specific needs.

