    if rolls.count(6) >= 3:
        return CRITICAL
    if 6 in rolls:
        return SUCCESS
    if rolls.count(5) >= 3:
        return SUCCESS
    if 5  in rolls:
        return PARTIAL
    if 4 in rolls:
        return PARTIAL
    return FAIL

