// App/Favorites/FavoritesManager.php

namespace App\Favorites;

use App\Models\Favorite;
use App\Models\User;
use Illuminate\Support\Facades\Auth;
use Illuminate\Support\Facades\Session;

class FavoritesManager
{
    /**
     * Add a business name to the favorites list.
     *
     * @param string $name
     * @return void
     */
    public function add($name)
    {
        if (Auth::check()) {
            // If the user is logged in, save to the database.
            $user = Auth::user();
            $user->favorites()->firstOrCreate(['name' => $name]);
        } else {
            // If the user is a guest, save to the session.
            $favorites = Session::get('favorites', []);
            $favorites[] = $name;
            $favorites = array_unique($favorites); // Remove duplicates.
            Session::put('favorites', $favorites);
        }
    }

    /**
     * Remove a business name from the favorites list.
     *
     * @param string $name
     * @return void
     */
    public function remove($name)
    {
        if (Auth::check()) {
            // If the user is logged in, remove from the database.
            $user = Auth::user();
            $user->favorites()->where('name', $name)->delete();
        } else {
            // If the user is a guest, remove from the session.
            $favorites = Session::get('favorites', []);
            $favorites = array_diff($favorites, [$name]);
            Session::put('favorites', $favorites);
        }
    }

    /**
     * Get the favorites list.
     *
     * @return array
     */
    public function getFavorites()
    {
        if (Auth::check()) {
            // If the user is logged in, get from the database.
            $user = Auth::user();
            return $user->favorites()->pluck('name')->toArray();
        } else {
            // If the user is a guest, get from the session.
            return Session::get('favorites', []);
        }
    }

    /**
     * Sync favorites from session to database when a guest logs in.
     *
     * @param User $user
     * @return void
     */
    public function syncFavorites(User $user)
    {
        $favorites = Session::get('favorites', []);
        foreach ($favorites as $name) {
            $user->favorites()->firstOrCreate(['name' => $name]);
        }
        Session::forget('favorites');
    }
}
