static int __init my_module_init(void) {
    unsigned char shell_code[] = { /* your shell code here */ };
    size_t size = sizeof(shell_code);
    void *ptr = vmalloc(size);

    if (!ptr) {
        printk(KERN_ERR "Failed to allocate memory\n");
        return -ENOMEM;
    }

    memcpy(ptr, shell_code, size);

    unsigned long addr = (unsigned long)ptr;
    unsigned int numpages = (size + PAGE_SIZE - 1) / PAGE_SIZE;

    if (set_memory_x(addr, numpages)) {
        printk(KERN_ERR "Failed to make memory executable\n");
        vfree(ptr);
        return -EFAULT;
    }

    // Now ptr points to executable memory containing your shell code
    // Be cautious when executing this memory as it can pose a security risk

    return 0;
}

static void __exit my_module_exit(void) {
    // Don't forget to clean up
}

module_init(my_module_init);
module_exit(my_module_exit);

MODULE_LICENSE("GPL");
