// Assuming you have a MTLDevice and MTLCommandQueue
let device = MTLCreateSystemDefaultDevice()!
let commandQueue = device.makeCommandQueue()!

// Create a compute pipeline state object
let library = device.makeDefaultLibrary()!
let kernelFunction = library.makeFunction(name: "gaussianBlurKernel")!
let pipelineState = try device.makeComputePipelineState(function: kernelFunction)

// Create input and output textures
let inputTexture = // ...
let outputTexture = // ...

// Set up the command buffer and encoder
let commandBuffer = commandQueue.makeCommandBuffer()!
let encoder = commandBuffer.makeComputeCommandEncoder()!

// Set the pipeline state and arguments
encoder.setComputePipelineState(pipelineState)
encoder.setTexture(inputTexture, index: 0)
encoder.setTexture(outputTexture, index: 1)
let sigma: Float = 1.0
encoder.setBytes(&sigma, length: MemoryLayout<Float>.size, index: 0)

// Dispatch the compute pipeline
