**Frontend (React)**

Create a new React app in a separate directory:
```bash
npx create-react-app todo-app
```

Install the required dependencies:
```bash
npm install axios
```

Replace the contents of `src/App.js` with:
```javascript
// src/App.js
import React, { useState, useEffect } from 'react';
import axios from 'axios';

function App() {
  const [todos, setTodos] = useState([]);
  const [description, setDescription] = useState('');

  useEffect(() => {
    getTodos();
  }, []);

  const getTodos = async () => {
    try {
      const res = await axios.get('http://localhost:5000/todos');
      setTodos(res.data);
    } catch (err) {
      console.error(err.message);
    }
  };

  const addTodo = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/todos', {
        description,
      });
      setTodos([...todos, res.data]);
      setDescription('');
    } catch (err) {
      console.error(err.message);
    }
  };

  const toggleCompleted = async (id, completed) => {
    try {
      await axios.put(`http://localhost:5000/todos/${id}`, {
        completed: !completed,
      });
      setTodos(
        todos.map((todo) =>
          todo.id === id ? { ...todo, completed: !completed } : todo
        )
      );
    } catch (err) {
      console.error(err.message);
    }
  };

  const deleteTodo = async (id) => {
    try {
      await axios.delete(`http://localhost:5000/todos/${id}`);
      setTodos(todos.filter((todo) => todo.id !== id));
    } catch (err) {
      console.error(err.message);
    }
  };

  return (
    <div>
      <h1>To-Do List</h1>
      <form onSubmit={addTodo}>
        <input
          type="text"
          value={description}
          onChange={(e) => setDescription(e.target.value)}
          placeholder="Add new todo"
        />
        <button type="submit">Add</button>
      </form>
      <ul>
        {todos.map((todo) => (
          <li key={todo.id}>
            <input
              type="checkbox"
              checked={todo.completed}
              onChange={() => toggleCompleted(todo.id, todo.completed)}
            />
            <span style={{ textDecoration: todo.completed ? 'line-through' : 'none' }}>
              {todo.description}
            </span>
            <button onClick={() => deleteTodo(todo.id)}>Delete</button>
          </li>
        ))}
      </ul>
    </div>
  );
}

export default App;
```

**Start the app**

Start the backend server:
```bash
node server.js
```

Start the frontend development server:
```bash
npm start
```

Open your web browser and navigate to `http://localhost:3000`. You should see a To-Do List app with CRUD functionality.

**Greatest Common Divisor (GCD) Calculator in Java**

### Overview

This Java program calculates the greatest common divisor (GCD) of two positive integers entered by the user. The GCD is the largest number that divides both integers without leaving a remainder.

### Code

```java
import java.util.InputMismatchException;
import java.util.Scanner;

public class GCD {
    /**
     * Calculates the greatest common divisor (GCD) of two positive integers.
     * @param num1 The first positive integer.
     * @param num2 The second positive integer.
     * @return The GCD of num1 and num2.
     */
    public static int calculateGCD(int num1, int num2) {
        if (num2 == 0) {
            return num1;
        } else {
            return calculateGCD(num2, num1 % num2);
        }
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Prompt user to enter two positive integers
        int num1 = getPositiveInteger(scanner, "Enter the first positive integer: ");
        int num2 = getPositiveInteger(scanner, "Enter the second positive integer: ");

        // Calculate and display the GCD
        int gcd = calculateGCD(num1, num2);
        System.out.println("The GCD of " + num1 + " and " + num2 + " is: " + gcd);

        scanner.close();
    }

    /**
     * Prompts the user to enter a positive integer and handles invalid inputs.
     * @param scanner The Scanner object to read user input.
     * @param prompt The prompt to display to the user.
     * @return A positive integer entered by the user.
     */
    private static int getPositiveInteger(Scanner scanner, String prompt) {
        while (true) {
            try {
                System.out.print(prompt);
                int num = scanner.nextInt();
                if (num <= 0) {
                    System.out.println("Please enter a positive integer.");
                } else {
                    return num;
                }
            } catch (InputMismatchException e) {
                System.out.println("Invalid input. Please enter a positive integer.");
                scanner.next(); // Clear invalid input
            }
        }
    }
}
```

### Explanation

1. The `calculateGCD` method uses the Euclidean algorithm to recursively calculate the GCD of two positive integers.
2. The `main` method creates a `Scanner` object to read user input and prompts the user to enter two positive integers.
3. The `getPositiveInteger` method is used to handle invalid inputs and ensure that the user enters a positive integer.
4. The GCD is calculated and displayed to the user.

### Example Usage

1. Run the program.
2. Enter two positive integers when prompted (e.g., 48 and 18).
3. The program will display the GCD of the two integers (e.g., 6).

