    isDropdownOpen(index) {
      return this.openDropdown === index;
    },
    toggleSubmenu(subIndex, index) {
      if (!this.openSubmenu[index]) {
        this.openSubmenu[index] = [];
      }
      const subIndexInOpen = this.openSubmenu[index].indexOf(subIndex);
      if (subIndexInOpen !== -1) {
        this.openSubmenu[index].splice(subIndexInOpen, 1);
      } else {
        this.openSubmenu[index].push(subIndex);
      }
    },
    isSubmenuOpen(subIndex, index) {
